module.exports = (bot) => {
    const answer = {
        text: async (ctx) => {
            return ctx.reply(await getPrompt(29));
        },
        //task
        task: async (ctx) => {
            const score = await requestScore(ctx);
            const response = ctx.chat.id.toString();
            return {score: score, response: response}
        },
    }
    bot.registerTask(answer);
}



